alter type public.subscription_status add value if not exists 'incomplete'; alter type public.subscription_status add value if not exists 'incomplete_expired'; alter table public.plans add column stripe_product_id text, add column stripe_price_id text unique, add column max_active_leads integer; create table public.business_billing(business_id uuid primary key references public.businesses(id) on delete cascade,stripe_customer_id text unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create trigger set_business_billing_updated_at before update on public.business_billing for each row execute function public.set_updated_at(); create table public.stripe_webhook_events(id uuid primary key default gen_random_uuid(),stripe_event_id text not null unique,type text not null,created_at timestamptz not null default now()); create index stripe_webhook_events_type_idx on public.stripe_webhook_events(type); alter table public.business_billing enable row level security; alter table public.stripe_webhook_events enable row level security; create policy "Owners view their own billing record" on public.business_billing for select to authenticated using(public.owns_business(business_id)); create policy "Admins manage business billing" on public.business_billing for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "Admins view webhook events" on public.stripe_webhook_events for select to authenticated using(public.is_admin());